  const pollBaseOf = (house, facet, p) => {
    if (house === "DemosAU" && p?.undecided != null) return "D";
    const b = house && pollBases[house];
    if (!b) return null;
    return typeof b === "string" ? b : (b[facet] || b.primary);
  };
